entry.before:
// 고칠 곳: 프레임이 다 올 때까지 여기서 계속 읽으며 기다려요.
while (!hasFrame(conn)) {
    if (readAvailable(ch, conn) < 0) { ch.close(); return; }
}

entry.after:
// 고친 곳: 읽을 수 있다는 알림은 "프레임이 다 왔다"는 뜻이 아니에요.
// 아직 다 오지 않았으면 기다리지 않고 루프로 돌아가요. 앞부분은 이 연결의 pending에 남아요.
// 다음 알림 때 나머지가 pending 뒤에 붙고, 그때 프레임을 꺼내요.
if (!hasFrame(conn)) return;
